mapper.select:
select o.id, o.status, o.total
from purchase_order o

  o.tenant_id = #{tenantId}
  and o.status = #{status}
  and o.total >= #{minTotal}
  and o.deleted_at is null

order by o.id

select o.id, o.total, i.number, i.status as invoice_status
from purchase_order o
join invoice i on i.order_id = o.id and i.tenant_id = o.tenant_id
where o.tenant_id = #{tenantId}
and i.status = #{status}

select it.order_id, it.product_id, it.quantity
from order_item it
where it.tenant_id = #{tenantId}
  and it.order_id in
  #{id}
